public class InnerCapacityProviderEc2ConfigurationFactory(Action<Humidifier.BedrockAgentCore.CapacityProviderTypes.Ec2Configuration> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.CapacityProviderTypes.Ec2Configuration>
{

    internal InnerCapacityProviderInstanceLifecycleConfigurationFactory LifecycleConfigurationFactory { get; set; }

    internal InnerCapacityProviderVpcConfigurationFactory VpcConfigurationFactory { get; set; }

    internal InnerCapacityProviderRootVolumeConfigurationFactory RootVolumeFactory { get; set; }

    internal InnerCapacityProviderLaunchTemplateSourceFactory LaunchTemplateSourceFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.CapacityProviderTypes.Ec2Configuration Create()
    {
        var ec2ConfigurationResult = CreateEc2Configuration();
        factoryAction?.Invoke(ec2ConfigurationResult);

        return ec2ConfigurationResult;
    }

    private Humidifier.BedrockAgentCore.CapacityProviderTypes.Ec2Configuration CreateEc2Configuration()
    {
        var ec2ConfigurationResult = new Humidifier.BedrockAgentCore.CapacityProviderTypes.Ec2Configuration();

        return ec2ConfigurationResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.CapacityProviderTypes.Ec2Configuration result)
    {
        base.CreateChildren(result);

        result.LifecycleConfiguration ??= LifecycleConfigurationFactory?.Build();
        result.VpcConfiguration ??= VpcConfigurationFactory?.Build();
        result.RootVolume ??= RootVolumeFactory?.Build();
        result.LaunchTemplateSource ??= LaunchTemplateSourceFactory?.Build();
    }

} // End Of Class

